<?php
session_start();require_once '../shared/config.php';require_once '../shared/security.php';require_once '../shared/rental_tracking.php';o2oCsrfToken();requireLogin('vendor','login.php');$db=getDB();$vendorId=(int)$_SESSION['vendor_id'];
$message='';$error='';$uploadDir=dirname(__DIR__).'/uploads/condition-reports/';$uploadWeb='../uploads/condition-reports/';if(!is_dir($uploadDir))@mkdir($uploadDir,0755,true);

if($_SERVER['REQUEST_METHOD']==='POST'){
  try{o2oRequireCsrf();}catch(Throwable $e){$error='Your session token expired. Please reload and try again.';}
  $action=$_POST['action']??'';$itemId=(int)($_POST['item_id']??0);$orderId=(int)($_POST['order_id']??0);
  $itemSt=$db->prepare("SELECT id FROM items WHERE id=? AND vendor_id=? LIMIT 1");$itemSt->execute([$itemId,$vendorId]);$item=$itemSt->fetch();
  $order=null;
  if(!$error&&$orderId>0){$orderSt=$db->prepare("SELECT id,item_id,status FROM orders WHERE id=? AND vendor_id=? LIMIT 1");$orderSt->execute([$orderId,$vendorId]);$order=$orderSt->fetch();if(!$order)$error='Rental order not found for this vendor.';elseif((int)$order['item_id']!==$itemId)$error='The rental order does not match the selected item.';}
  if(!$error&&!$item)$error='Item not found in your inventory.';
  elseif(!$error&&$action==='condition'){
    $type=$_POST['inspection_type']??'manual';$score=(float)($_POST['condition_score']??0);$notes=trim($_POST['notes']??'');$reportImage=null;
    if(!in_array($type,['before_rental','after_return','manual'],true))$error='Invalid inspection type.';
    elseif($score<0||$score>100)$error='Condition score must be between 0 and 100.';
    elseif(isset($_FILES['report_image'])&&$_FILES['report_image']['error']!==UPLOAD_ERR_NO_FILE){
      if($_FILES['report_image']['error']!==UPLOAD_ERR_OK)$error='Condition image upload failed.';
      elseif($_FILES['report_image']['size']>5*1024*1024)$error='Condition image must be 5MB or smaller.';
      else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['report_image']['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))$error='Use JPG, PNG or WEBP for condition photos.';else{$fn='condition_'.bin2hex(random_bytes(8)).'.'.$allowed[$mime];if(!move_uploaded_file($_FILES['report_image']['tmp_name'],$uploadDir.$fn))$error='Could not save condition image.';else$reportImage=$fn;}}
    }
    if(!$error){$st=$db->prepare("INSERT INTO condition_reports (item_id,rental_order_id,created_by_vendor_id,inspection_type,condition_score,notes,image_path) VALUES (?,?,?,?,?,?,?)");$st->execute([$itemId,$orderId?:null,$vendorId,$type,$score,$notes,$reportImage]);if($orderId>0&&$type==='after_return')o2oRentalRecordEvent($db,$orderId,$vendorId,'inspected','After-return condition inspection recorded.');$message='Condition report saved.';}
  }elseif($action==='sanitize'){
    $status=$_POST['sanitize_status']??'completed';$notes=trim($_POST['sanitize_notes']??'');
    if(!in_array($status,['pending','in_progress','completed'],true))$error='Invalid sanitization status.';
    else{$completed=$status==='completed'?date('Y-m-d H:i:s'):null;$st=$db->prepare("INSERT INTO sanitization_records (item_id,rental_order_id,created_by_vendor_id,status,completed_at,notes) VALUES (?,?,?,?,?,?)");$st->execute([$itemId,$orderId?:null,$vendorId,$status,$completed,$notes]);if($orderId>0&&$status==='completed')o2oRentalRecordEvent($db,$orderId,$vendorId,'sanitized','Sanitization completed.');$message='Sanitization record saved.';}
  }else $error='Invalid trust action.';
}

$itemsStmt=$db->prepare("SELECT i.id,i.name,i.image_path FROM items i WHERE i.vendor_id=? ORDER BY i.name");$itemsStmt->execute([$vendorId]);$items=$itemsStmt->fetchAll();
$reportsStmt=$db->prepare("SELECT cr.*,i.name item_name,o.id rental_order_id FROM condition_reports cr JOIN items i ON i.id=cr.item_id LEFT JOIN orders o ON o.id=cr.rental_order_id WHERE i.vendor_id=? ORDER BY cr.created_at DESC");$reportsStmt->execute([$vendorId]);$reports=$reportsStmt->fetchAll();
$sanStmt=$db->prepare("SELECT sr.*,i.name item_name,o.id rental_order_id FROM sanitization_records sr JOIN items i ON i.id=sr.item_id LEFT JOIN orders o ON o.id=sr.rental_order_id WHERE i.vendor_id=? ORDER BY sr.created_at DESC");$sanStmt->execute([$vendorId]);$san=$sanStmt->fetchAll();
?>
<!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trust Records – O2O Tradition</title><style>
body{font-family:Arial,sans-serif;background:#F4F7F4;color:#1A2E1A;margin:0}.nav{background:#0F1B2D;color:#C9A84C;padding:18px 28px;display:flex;justify-content:space-between}.nav a{color:#E8CC82;text-decoration:none;margin-left:15px}.main{max-width:1100px;margin:auto;padding:30px}.card{background:#fff;padding:22px;margin:15px 0;box-shadow:0 2px 10px #0001}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.row{margin-bottom:14px}.label{display:block;font-size:12px;font-weight:bold;margin-bottom:6px}.input,.select,.textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #ddd;font:14px Arial}.textarea{min-height:80px}.button{background:#0F1B2D;color:#C9A84C;border:0;padding:11px 16px;font-weight:bold}.notice{padding:12px;background:#F0FDF4;color:#166534;border:1px solid #BBF7D0;margin-bottom:15px}.error{padding:12px;background:#FEF2F2;color:#991B1B;border:1px solid #FECACA;margin-bottom:15px}.record{padding:12px 0;border-bottom:1px solid #eee}.badge{display:inline-block;padding:4px 8px;font-size:11px;background:#FEF3C7}.done{background:#D1FAE5;color:#065F46}.photo{width:80px;height:80px;object-fit:cover;margin-top:8px}@media(max-width:700px){.grid{grid-template-columns:1fr}.nav{padding:15px}}
</style></head><body>
<div class="nav"><div>O2O Tradition · Trust Records</div><div><a href="dashboard.php">Dashboard</a><a href="inventory.php">Inventory</a><a href="verification.php">Verification</a><a href="logout.php">Logout</a></div></div>
<main class="main"><h1>Condition & Sanitization</h1><p style="color:#666">Keep a transparent record of item condition before/after rentals and sanitization status.</p>
<?php if($message):?><div class="notice">✓ <?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?>
<div class="grid"><div class="card"><h2>Condition Report</h2><form method="POST" enctype="multipart/form-data"><input type="hidden" name="action" value="condition"><div class="row"><label class="label">Item</label><select class="select" name="item_id" required><?php foreach($items as $i):?><option value="<?=$i['id']?>"><?=htmlspecialchars($i['name'])?></option><?php endforeach;?></select></div><div class="row"><label class="label">Rental order ID (optional)</label><input class="input" type="number" name="order_id" min="0"></div><div class="row"><label class="label">Inspection type</label><select class="select" name="inspection_type"><option value="before_rental">Before rental</option><option value="after_return">After return</option><option value="manual">Manual</option></select></div><div class="row"><label class="label">Condition score (0–100)</label><input class="input" type="number" name="condition_score" min="0" max="100" step="0.01" value="100" required></div><div class="row"><label class="label">Notes</label><textarea class="textarea" name="notes"></textarea></div><div class="row"><label class="label">Condition photo</label><input class="input" type="file" name="report_image" accept="image/jpeg,image/png,image/webp"></div><button class="button">Save Condition Report</button></form></div>
<div class="card"><h2>Sanitization Record</h2><form method="POST"><input type="hidden" name="action" value="sanitize"><div class="row"><label class="label">Item</label><select class="select" name="item_id" required><?php foreach($items as $i):?><option value="<?=$i['id']?>"><?=htmlspecialchars($i['name'])?></option><?php endforeach;?></select></div><div class="row"><label class="label">Rental order ID (optional)</label><input class="input" type="number" name="order_id" min="0"></div><div class="row"><label class="label">Status</label><select class="select" name="sanitize_status"><option value="pending">Pending</option><option value="in_progress">In progress</option><option value="completed" selected>Completed</option></select></div><div class="row"><label class="label">Notes</label><textarea class="textarea" name="sanitize_notes"></textarea></div><button class="button">Save Sanitization Record</button></form></div></div>
<div class="card"><h2>Recent Condition Reports</h2><?php if($reports):foreach($reports as $r):?><div class="record"><b><?=htmlspecialchars($r['item_name'])?></b> · <?=htmlspecialchars(ucwords(str_replace('_',' ',$r['inspection_type'])))?> · Score <?=number_format($r['condition_score'],1)?>/100<div style="font-size:12px;color:#777"><?=date('d M Y, h:i A',strtotime($r['created_at']))?><?php if($r['rental_order_id']):?> · Rental #<?=str_pad($r['rental_order_id'],6,'0',STR_PAD_LEFT)?><?php endif;?></div><div><?=nl2br(htmlspecialchars($r['notes']))?></div><?php if($r['image_path']):?><img class="photo" src="<?=$uploadWeb.htmlspecialchars($r['image_path'])?>" alt="Condition report"><?php endif;?></div><?php endforeach;else:?><p style="color:#888">No condition reports yet.</p><?php endif;?></div>
<div class="card"><h2>Recent Sanitization Records</h2><?php if($san):foreach($san as $s):?><div class="record"><b><?=htmlspecialchars($s['item_name'])?></b> · <span class="badge <?=$s['status']==='completed'?'done':''?>"><?=htmlspecialchars(ucwords(str_replace('_',' ',$s['status'])))?></span><div style="font-size:12px;color:#777"><?=date('d M Y, h:i A',strtotime($s['created_at']))?><?php if($s['completed_at']):?> · Completed <?=date('d M Y, h:i A',strtotime($s['completed_at']))?><?php endif;?></div><div><?=nl2br(htmlspecialchars($s['notes']))?></div></div><?php endforeach;else:?><p style="color:#888">No sanitization records yet.</p><?php endif;?></div>
</main></body></html>